mapper.select:
SELECT m.*, su.username AS sender_username, COALESCE(su.name, m.sender_name) AS sender_name FROM message m LEFT JOIN user su ON su.id = m.sender_id AND su.deleted_at IS NULL WHERE m.receiver_id IS NULL AND m.deleted_at IS NULL
AND m.id < #{cursor}
ORDER BY m.id DESC LIMIT #{size}

SELECT m.*, su.username AS sender_username, COALESCE(su.name, m.sender_name) AS sender_name FROM message m LEFT JOIN user su ON su.id = m.sender_id AND su.deleted_at IS NULL WHERE m.deleted_at IS NULL AND ( (m.sender_id = #{userId} AND m.receiver_name = #{targetName}) OR (m.sender_id = #{targetUserId} AND m.receiver_name = #{senderName}) )
AND m.id < #{cursor}
ORDER BY m.id DESC LIMIT #{size}

mapper.update:
UPDATE message
SET sender_name = #{newName}
WHERE sender_id = #{senderId} AND sender_name = #{oldName} AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*) AS unread_count,
       MAX(id)   AS last_message_id
FROM message
WHERE receiver_id = #{userId} AND sender_id = #{peerId}
  AND deleted_at IS NULL
  AND id > #{lastReadId}
